#!/usr/bin/env bash
# bindings.ts is generated by specta; it must always be regenerated and
# committed alongside any change to exported Rust types.
set -euo pipefail

cd "$(dirname "$0")/.."
(cd src-tauri && cargo run --quiet --bin export_bindings)
if ! git diff --exit-code -- src/api/bindings.ts; then
  echo "error: src/api/bindings.ts is stale — commit the regenerated file" >&2
  exit 1
fi
